CSS = r"""
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#050914;--panel:#0a1222;--panel2:#0d1930;--line:#1b2b48;--cyan:#48e5ff;--blue:#3987ff;--violet:#a78bfa;--rose:#ff648c;--amber:#ffbd69;--green:#50e3ad;--white:#f3f7ff;--muted:#8292ad}
*{box-sizing:border-box}
body{background:#050914!important;color:var(--white)!important}
.gradio-container{max-width:1600px!important;background:radial-gradient(ellipse at 52% -15%,#142a50 0%,#080f20 42%,#050914 78%)!important;color:var(--white)!important;font-family:'Manrope',Inter,Arial,sans-serif!important;padding:22px clamp(10px,2.2vw,34px) 16px!important}
footer{display:none!important}.action-app{min-height:100vh}
.hero-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 22px;border:1px solid #20385d;border-radius:17px;background:linear-gradient(110deg,rgba(14,31,58,.96),rgba(7,15,30,.96));box-shadow:0 14px 50px #0005,inset 0 1px #ffffff0b;position:relative;overflow:hidden}
.hero-header:after{content:"";position:absolute;right:-80px;top:-140px;width:360px;height:260px;background:#268dff1b;filter:blur(45px);pointer-events:none}
.hero-brand{display:flex;align-items:center;gap:16px;min-width:0}.brand-symbol{width:54px;height:54px;display:grid;place-items:center;position:relative;border:1px solid #3d9cff88;border-radius:15px;background:linear-gradient(145deg,#123c70,#101d3b);box-shadow:0 0 25px #168bff28,inset 0 0 18px #42dfff16;flex-shrink:0}
.brand-symbol span{font:800 16px 'DM Mono',monospace;letter-spacing:-1px;color:#8feaff;text-shadow:0 0 12px #37dfff}.brand-symbol i{position:absolute;width:7px;height:7px;right:7px;top:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}
.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:1.6px;color:#6e91bf}.brand-title{font-size:clamp(20px,2.8vw,29px);font-weight:800;letter-spacing:1.1px;color:#fff;line-height:1.3}.brand-title span{color:var(--cyan);text-shadow:0 0 18px #48e5ff35}.brand-subtitle{font-size:12px;color:#9aacc8;margin-top:3px}
.header-meta{display:flex;flex-direction:column;align-items:flex-end;gap:9px;z-index:1}.engine-chip{display:flex;align-items:center;gap:8px;border:1px solid #295b65;background:#0b292c;border-radius:30px;padding:7px 12px;color:#7ce9d1;font:500 10px 'DM Mono',monospace;letter-spacing:.8px}
.pulse-dot{width:7px;height:7px;border-radius:50%;background:#50e3ad;box-shadow:0 0 10px #50e3ad;animation:pulse 2s infinite}.version-label{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#6f809d}.version-label b{color:#9fb5d5}
@keyframes pulse{50%{opacity:.35;box-shadow:0 0 2px #50e3ad}}
.welcome-row{display:flex;align-items:flex-end;justify-content:space-between;gap:15px;padding:25px 4px 17px}.welcome-row h1{font-size:clamp(22px,3vw,30px);font-weight:800;letter-spacing:-.8px;margin:5px 0 3px;color:#f4f8ff}.welcome-row p{margin:0;color:#91a2bd;font-size:13px}
.workspace-tag{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#8ea6c8;border:1px solid #243a5c;background:#0b172b;padding:8px 11px;border-radius:7px;white-space:nowrap}.tiny-square{display:inline-block;width:6px;height:6px;background:var(--cyan);margin-right:7px;box-shadow:0 0 8px var(--cyan)}
.app-tabs{gap:8px!important}.app-tabs [role=tablist]{border-bottom:1px solid #1c2d49!important;gap:5px!important;margin-bottom:15px!important}.app-tabs button[role=tab]{color:#91a3bf!important;border:1px solid transparent!important;border-radius:8px 8px 0 0!important;background:transparent!important;padding:11px 16px!important;font-size:12px!important;font-weight:700!important;transition:.2s ease!important}
.app-tabs button[role=tab][aria-selected=true]{color:#eafaff!important;background:linear-gradient(180deg,#12345b,#0a1b31)!important;border-color:#2c80b5!important;border-bottom-color:#48e5ff!important;box-shadow:0 5px 22px #1a9de51b!important}
.panel{background:linear-gradient(145deg,rgba(13,26,47,.98),rgba(8,16,31,.98))!important;border:1px solid #203653!important;border-radius:14px!important;padding:17px!important;min-width:0!important;box-shadow:0 12px 35px #0003,inset 0 1px #ffffff08!important}
.top-grid,.lower-grid,.analytics-grid{align-items:stretch!important;gap:14px!important}.panel-topline{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.section-title{font-size:17px;font-weight:800;letter-spacing:-.3px;color:#edf5ff;margin-top:3px}
.state-pill{font:10px 'DM Mono',monospace;letter-spacing:.8px;color:#70e7c4;border:1px solid #276558;background:#0c2828;padding:5px 9px;border-radius:5px;white-space:nowrap}.metric-caption{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#657c9d}
.video-panel{border-color:#29476d!important}.video-input{border:1px solid #1c3455!important;border-radius:10px!important;overflow:hidden!important;background:#030914!important}.video-input video{max-height:390px!important;object-fit:contain!important;background:radial-gradient(ellipse,#101f39,#030711)!important}.video-input>div{border-radius:10px!important}
.status-message{font-size:12px!important;color:#a9bad2!important;background:#0b1b30!important;border:1px solid #1c3657!important;border-left:3px solid var(--cyan)!important;border-radius:7px!important;padding:10px 12px!important;margin:11px 0!important}.status-message p{margin:0!important}
.video-actions{gap:9px!important;margin:8px 0 4px!important}button{min-height:40px!important;border-radius:8px!important;font-family:'Manrope',sans-serif!important;font-size:12px!important;font-weight:700!important;transition:transform .18s ease,box-shadow .18s ease,border-color .18s ease!important}button:hover{transform:translateY(-1px)!important;box-shadow:0 6px 20px #168bff28!important}
button.primary,.start-action{background:linear-gradient(105deg,#1263d8,#168edb)!important;border:1px solid #54dfff!important;color:#fff!important;box-shadow:0 5px 18px #087bff2c!important}button.secondary,.stop-action{background:#101f37!important;border:1px solid #294365!important;color:#c6d8f1!important}.download-action{width:100%!important;margin-top:8px!important;background:linear-gradient(100deg,#102e43,#12334a)!important;border:1px solid #26758a!important;color:#9cecff!important}
.progress-control{margin-top:7px!important}.progress-control input[type=range],input[type=range]{accent-color:var(--cyan)!important}.progress-control label,.action-panel label,.controls-panel label{font:10px 'DM Mono',monospace!important;letter-spacing:1px!important;color:#8198b8!important}
.insights-panel{background:linear-gradient(145deg,#0e1c35,#091426)!important}.metric-row{gap:10px!important;margin-bottom:10px!important}.metric-card{background:linear-gradient(145deg,#122541,#0b172a)!important;border:1px solid #294360!important;border-radius:10px!important;padding:12px!important;min-width:0!important}.metric-card label{font:9px 'DM Mono',monospace!important;letter-spacing:.8px!important;color:#8da4c4!important}.metric-card input{font-size:29px!important;font-weight:800!important;color:#f3f8ff!important;padding:0!important;background:transparent!important;border:0!important}
.metric-cyan{border-top:2px solid var(--cyan)!important}.metric-violet{border-top:2px solid var(--violet)!important}.metric-rose{border-top:2px solid var(--rose)!important}.metric-amber{border-top:2px solid var(--amber)!important}.metric-cyan input{color:var(--cyan)!important}.metric-violet input{color:var(--violet)!important}.metric-rose input{color:var(--rose)!important}.metric-amber input{color:var(--amber)!important}
.insight-note{display:flex;align-items:center;gap:11px;padding:12px;border:1px solid #263e5d;border-radius:9px;background:#0b1b30;margin-top:6px}.note-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:8px;background:#12344a;color:var(--cyan);font-size:17px}.insight-note b,.insight-note span{display:block}.insight-note b{font-size:11px;color:#dceaff}.insight-note span{font-size:10px;color:#8297b6;margin-top:3px;line-height:1.5}
.mini-divider{height:1px;background:#1b2e49;margin:15px 0 11px}.quick-facts{display:grid;grid-template-columns:1fr 1fr;gap:12px}.quick-facts span,.quick-facts b{display:block}.quick-facts span{font:9px 'DM Mono',monospace;letter-spacing:1px;color:#637b9c}.quick-facts b{font-size:11px;color:#b7c9e2;margin-top:4px}
.lower-grid{margin-top:14px!important}.action-panel input[type=range]{accent-color:var(--cyan)!important}.action-panel .wrap,.controls-panel .wrap{margin-bottom:10px!important}.select-row{gap:10px!important}
.controls-panel input,.controls-panel textarea,.controls-panel select,.controls-panel [role=combobox]{background:#0b1a30!important;color:#e7f1ff!important;border:1px solid #294361!important;border-radius:8px!important}.controls-panel .utility-actions{gap:8px!important;margin-top:7px!important}.utility-actions button{flex:1}
.gradio-plot{background:transparent!important;min-width:0!important;border:0!important}.gradio-plot .plot-container{border-radius:8px!important}.analytics-grid{gap:14px!important}
.dataframe{overflow-x:auto!important;border:1px solid #243a58!important;border-radius:9px!important}.dataframe table{background:#0a172a!important;color:#dce9fb!important}.dataframe th{background:#102542!important;color:#8feaff!important;font:10px 'DM Mono',monospace!important}.dataframe td{border-color:#1b304c!important;font-size:12px!important}
.empty-events{color:#8297b6!important;font-size:12px!important}.settings-panel{max-width:900px}.settings-panel .prose{color:#a9bad2!important}.settings-panel strong{color:#e8f4ff}
.app-footer{display:flex;justify-content:space-between;gap:12px;padding:18px 4px 5px;color:#5f7391;font:9px 'DM Mono',monospace;letter-spacing:1px}.app-footer b,.app-footer i{color:var(--cyan);font-style:normal}
@media(max-width:900px){.top-grid,.lower-grid,.analytics-grid{flex-direction:column!important}.top-grid>div,.lower-grid>div,.analytics-grid>div{width:100%!important}.video-input video{max-height:340px!important}}
@media(max-width:600px){.gradio-container{padding:9px 8px 12px!important}.hero-header{padding:13px;border-radius:12px}.brand-symbol{width:43px;height:43px;border-radius:12px}.brand-title{font-size:20px}.brand-subtitle{font-size:10px;max-width:230px}.eyebrow{font-size:9px}.header-meta{gap:6px}.engine-chip{font-size:8px;padding:6px 8px}.version-label{font-size:8px}.welcome-row{padding:19px 3px 13px;align-items:flex-start}.welcome-row p{font-size:11px;max-width:260px}.workspace-tag{font-size:8px;padding:7px}.app-tabs button[role=tab]{font-size:10px!important;padding:9px 8px!important;white-space:nowrap}.panel{padding:12px!important;border-radius:11px!important}.section-title{font-size:15px}.video-input video{max-height:245px!important}.metric-card{padding:9px!important}.metric-card input{font-size:24px!important}.metric-card label{font-size:8px!important}.select-row{flex-wrap:wrap!important}.select-row>div{min-width:100%!important}.app-footer{font-size:8px;flex-direction:column}.video-actions button{font-size:11px!important}}
@media(max-width:380px){.brand-subtitle,.version-label{display:none}.header-meta{align-self:flex-start}.welcome-row{flex-direction:column}.workspace-tag{align-self:flex-start}.app-tabs button[role=tab]{padding:8px 6px!important;font-size:9px!important}}
"""